#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> myMap;  // Creates a red-black tree to store string keys and int values
    myMap["apple"] = 1;  // Inserts or updates a node; if 'apple' exists, updates value; otherwise, inserts a new node and balances the tree
    myMap["banana"] = 2;  // Similar insertion, maintaining sorted order
    std::cout << myMap["apple"] << std::endl;  // Performs a binary search on the tree to locate the node for 'apple'
    return 0;
}
